contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: set an initial MinSum, initialize, then try to set MinSum again.
    // The rule: after Initialized() the MinSum getter must still return the original value.
    function run(uint initialVal, uint newVal) public {
        // Set initial MinSum (allowed before initialization)
        c.SetMinSum(initialVal);
        // Mark contract initialized
        c.Initialized();
        // Attempt to change MinSum after initialization. In the original contract P this reverts,
        // so the call will not succeed and MinSum remains initialVal. In mutant M it will succeed
        // and change MinSum to newVal.
        // We perform the call and catch reversion via low-level call so execution continues.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newVal));

        // Read MinSum and assert it equals the original value. On P this holds (ok will be false),
        // on M the call succeeds and MinSum != initialVal, violating the assertion.
        uint cur = c.MinSum();
        assert(cur == initialVal);
    }

    // Allow this contract to hold ETH if needed by tests (not used here).
    receive() external payable {}
}

