contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive: call SetMinSum twice with two input values; on original P the first call sets MinSum and locks initialization
    // so the second call should revert and MinSum should equal the first value. The mutant sets intitalized=true on first call
    // too, but still sets MinSum on that first call; however the mutant also sets intitalized on first call which matches behavior
    // The distinguishing difference is that in P SetMinSum does not set intitalized, so calling SetMinSum twice with different callers
    // allows the second caller to set MinSum if Initialized() hasn't been called. To separate them we will call Initialized() in between
    // but the mutant will have intitalized already true after first SetMinSum, so calling Initialized() after first call will not change.

    // However per instruction we must target the single-statement change: mutant sets intitalized=true when setting MinSum.
    // The simplest distinguishing sequence: call SetMinSum once from this contract, then call Initialized() from this contract, then try to call SetMinSum again —
    // on original P the first SetMinSum does NOT set intitalized, so Initialized() will set intitalized=true and then second SetMinSum will revert.
    // On mutant, first SetMinSum already set intitalized=true, so calling Initialized() has no effect, and the second SetMinSum will revert as well.
    // That does not distinguish. Instead, we must use two different callers: if another external actor calls SetMinSum first on P, it sets MinSum but not intitalized,
    // so this contract can call SetMinSum afterwards and overwrite MinSum — but on mutant the first caller's SetMinSum sets intitalized=true preventing overwrite.
    // We cannot create another caller in this test, but we can emulate by using fallback payable with different msg.sender? Not allowed.

    // To adhere to the rules and be distinguishing with only this contract as caller, we exploit that SetLogFile also checks intitalized; but the mutation only affects SetMinSum.
    // Construct a test where: first call SetMinSum with value a, then call SetLogFile (which on P is allowed only if not intitalized). Then call SetMinSum again with value b.
    // On P, since SetMinSum did NOT set intitalized, SetLogFile will succeed (it does not set intitalized), and second SetMinSum will also succeed and overwrite MinSum.
    // On mutant, first SetMinSum sets intitalized=true, so SetLogFile will revert, preventing reaching the second SetMinSum. We capture that via a boolean try/catch.

    // Public test function: takes two uints and an address for log, attempts the sequence and asserts that either SetLogFile succeeded and MinSum equals second value (P),
    // or SetLogFile reverted (M). We must assert a property that holds on P for all inputs and is violated by M. So assert that SetLogFile call does NOT revert and MinSum==second value.
    // That holds on P but is false on M (since SetLogFile will revert on M). Thus the property is distinguishing.

    function check(uint v1, uint v2, address logAddr) public {
        // first set MinSum to v1
        c.SetMinSum(v1);

        // attempt to set LogFile; on P this should NOT revert (since intitalized is still false), on M this will revert
        bool logSucceeded = true;
        try c.SetLogFile(logAddr) {
            // success
        } catch {
            logSucceeded = false;
        }

        // if SetLogFile succeeded, we can call SetMinSum again to set v2 (on P). If it reverted, this call would revert as well on M, so avoid calling.
        if (logSucceeded) {
            c.SetMinSum(v2);
        }

        // Now assert the distinguishing property: on P, SetLogFile must succeed and MinSum equals v2 after the overwrite.
        // We observe MinSum through its public getter.
        assert(logSucceeded && c.MinSum() == v2);
    }

    // fallback/receive not needed
}

