contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _val) public payable {
        // We require that Initialized() has not been called yet by insisting MinSum can be set:
        // Since we cannot read intitalized directly, we require that calling SetMinSum on the original should succeed.
        // For P this always holds: when not initialized, SetMinSum does not revert. We enforce the precondition
        // that Initialized() hasn't been called by calling SetMinSum once and requiring it does not revert.
        bool firstReverted;
        try c.SetMinSum(_val) { firstReverted = false; } catch { firstReverted = true; }
        require(!firstReverted);

        // Now record whether a subsequent call reverts. For P this second call may succeed (since P doesn't set intitalized),
        // but for the mutant it will revert because it sets intitalized on the first call.
        bool secondReverted;
        try c.SetMinSum(_val) { secondReverted = false; } catch { secondReverted = true; }

        // Assert the general rule: if the first call succeeded (i.e., contract was not initialized), then
        // the second call must also succeed in the original contract P. We express the rule as
        // "first call succeeded implies second call does not revert" over observed revert flags.
        assert(!firstReverted ==> !secondReverted);
    }
    // helper to use implication in solidity: define it as an internal pure function
    receive() external payable {}
}

