    function run(uint _val) public payable {
        // No precondition: we must express rule using only observable revert flag and parameters.
        bool reverted; try c.SetMinSum(_val) { reverted = false; } catch { reverted = true; }
        // In the original contract P, SetMinSum reverts iff intitalized was true.
        // We cannot read intitalized, so we express that if SetMinSum reverted then a second attempt also reverts
        // would be false in P (since original: first call succeeds when not initialized). However the mutant makes first call revert.
        // A robust observable rule: If the call reverted, then a subsequent call with the same argument also reverts.
        // This holds in original P only when intitalized was already true before both calls; but because original P's first call on uninitialized never reverts,
        // the universal rule that "if first reverts then second also reverts" holds in P (vacuously when first doesn't revert) and is violated by the mutant where first reverts but second may behave differently.
        bool reverted2; try c.SetMinSum(_val) { reverted2 = false; } catch { reverted2 = true; }
        assert(!reverted || reverted2);
    }
